package org.eclipse.kura.core.keystore;

import java.nio.charset.StandardCharsets;

import org.junit.Test;

public class AtomicFileTempCleanupTest extends AbstractAtomicFileWriterTest {

    @Test
    public void replacesStaleTempFileWhenWriting() throws Exception {
        givenTargetFile("data.bin", "old content");
        givenFile("data.bin.tmp", "stale content");

        whenContentIsWritten("new content");

        thenNoExceptionIsThrown();
        thenFileContains("data.bin", "new content");
        thenDirectoryContainsOnly("data.bin");
    }

    @Test
    public void deletesTempFile() throws Exception {
        givenTargetFile("data.bin", "current content");
        givenFile("data.bin.tmp", "stale content");

        whenTempFileIsDeleted();

        thenNoExceptionIsThrown();
        thenFileContains("data.bin", "current content");
        thenDirectoryContainsOnly("data.bin");
    }

    @Test
    public void deletesTempFileOfMissingTarget() throws Exception {
        givenTargetFile("data.bin");
        givenFile("data.bin.tmp", "stale content");

        whenTempFileIsDeleted();

        thenNoExceptionIsThrown();
        thenDirectoryContainsOnly();
    }

    @Test
    public void rejectsNullTarget() {
        givenNullTarget();

        whenTempFileIsDeleted();

        thenExceptionIsThrown(IllegalArgumentException.class);
    }

    private void whenContentIsWritten(final String content) {
        try {
            this.writer.write(this.target, out -> out.write(content.getBytes(StandardCharsets.UTF_8)));
        } catch (Exception e) {
            this.exception = e;
        }
    }

    private void whenTempFileIsDeleted() {
        try {
            this.writer.deleteTempFile(this.target);
        } catch (Exception e) {
            this.exception = e;
        }
    }
}
